import{_ as t,o as n,c as i,a2 as d}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Welche Einstellungen hat der Adapter und was bewirken sie?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"de/adapter/esphome/referenz/einstellungen.md","filePath":"de/adapter/esphome/referenz/einstellungen.md","lastUpdated":1795562976000}'),r={name:"de/adapter/esphome/referenz/einstellungen.md"};function a(s,e,o,l,c,u){return n(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="welche-einstellungen-hat-der-adapter-und-was-bewirken-sie" tabindex="-1">Welche Einstellungen hat der Adapter und was bewirken sie? <a class="header-anchor" href="#welche-einstellungen-hat-der-adapter-und-was-bewirken-sie" aria-label="Permalink to &quot;Welche Einstellungen hat der Adapter und was bewirken sie?&quot;">​</a></h1><p><a id="reconnect-settings-exist-happens-device"></a></p><h2 id="welche-reconnect-einstellungen-gibt-es-und-was-passiert-wenn-ein-gerat-offline-geht" tabindex="-1">Welche Reconnect-Einstellungen gibt es und was passiert, wenn ein Gerät offline geht? <a class="header-anchor" href="#welche-reconnect-einstellungen-gibt-es-und-was-passiert-wenn-ein-gerat-offline-geht" aria-label="Permalink to &quot;Welche Reconnect-Einstellungen gibt es und was passiert, wenn ein Gerät offline geht?&quot;">​</a></h2><p>Der Adapter verbindet sich nach jedem Verbindungsverlust von selbst neu, so lange, bis das Gerät wieder antwortet. Wie schnell er einen Ausfall bemerkt und wie oft er es neu versucht, stellst du im Reiter „Haupteinstellungen“ unter „Verbindungsverhalten für bekannte Geräte“ ein. Die Werte gelten für alle Geräte der Instanz.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Was es bewirkt</th><th>Standard</th><th>Erlaubt</th></tr></thead><tbody><tr><td>„Reconnect-Intervall (Sekunden)“</td><td>Wartezeit vor jedem neuen Verbindungsversuch</td><td>30</td><td>1 bis 3600</td></tr><tr><td>„Ping-Intervall (Sekunden)“</td><td>wie oft der Adapter ein verbundenes Gerät anpingt</td><td>5</td><td>1 bis 3600</td></tr><tr><td>„Ping-Versuche bis offline“</td><td>wie viele Pings hintereinander ausbleiben dürfen, bevor das Gerät als offline gilt</td><td>1</td><td>1 bis 100</td></tr></tbody></table><p>Der Hilfetext unter „Reconnect-Intervall“ nennt 5 Sekunden. Diesen Wert nimmt der Adapter nur, wenn das Feld leer ist. Es gilt, was im Feld steht.</p><p>Mit 5 Sekunden Ping-Intervall und 1 Ping-Versuch bemerkt der Adapter einen Ausfall nach etwa 5 Sekunden. Mit 3 Versuchen dauert es etwa 15 Sekunden, dafür trennt ein einzelner verlorener Ping im WLAN die Verbindung nicht.</p><h3 id="was-passiert-wenn-ein-gerat-offline-geht" tabindex="-1">Was passiert, wenn ein Gerät offline geht <a class="header-anchor" href="#was-passiert-wenn-ein-gerat-offline-geht" aria-label="Permalink to &quot;Was passiert, wenn ein Gerät offline geht&quot;">​</a></h3><ol><li>Der Adapter bemerkt den Abbruch, weil die Verbindung abreißt oder die eingestellten Pings ausbleiben.</li><li><code>esphome.0.&lt;Gerät&gt;.info._online</code> wird <code>false</code>, <code>info._connectionStatus</code> nennt den Grund.</li><li>Nach dem „Reconnect-Intervall“ baut der Adapter die Verbindung neu auf, ohne Obergrenze.</li><li>Antwortet das Gerät wieder, liest er Geräteinformationen und Entitäten neu ein. Im Log steht „ESPHome client &lt;IP&gt; connected“.</li></ol><p>Einen Neustart des Adapters brauchst du dafür nicht.</p><h3 id="die-statusanzeige" tabindex="-1">Die Statusanzeige <a class="header-anchor" href="#die-statusanzeige" aria-label="Permalink to &quot;Die Statusanzeige&quot;">​</a></h3><p><code>info._online</code> ist <code>true</code>, solange das Gerät verbunden ist, und hat die Rolle <code>indicator.reachable</code>. Der Reiter „Geräte“ zeigt denselben Status. <code>esphome.0.info.connectedDevices</code> listet die Namen aller verbundenen Geräte, <code>esphome.0.info.connection</code> ist <code>true</code>, solange die Instanz läuft.</p><p><code>info._connectionStatus</code> nennt den Zustand als Text:</p><table tabindex="0"><thead><tr><th>Wert</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>connecting</code>, <code>initializing</code>, <code>Initializing</code></td><td>Verbindung wird aufgebaut oder das Gerät eingelesen.</td></tr><tr><td><code>Connected</code>, <code>connected</code>, <code>initialized</code></td><td>Verbunden, die Werte kommen an.</td></tr><tr><td><code>disconnected</code></td><td>Getrennt, der nächste Versuch folgt nach dem „Reconnect-Intervall“.</td></tr><tr><td><code>connection lost</code></td><td>Verbindung abgerissen (<code>ECONNRESET</code>).</td></tr><tr><td><code>unreachable</code></td><td>Das Gerät antwortet nicht.</td></tr><tr><td><code>No Network</code></td><td>Das Netzwerk des ioBroker-Rechners ist noch nicht bereit.</td></tr><tr><td><code>API password incorrect</code></td><td>Das API-Passwort stimmt nicht.</td></tr><tr><td><code>Encryption Key Missing</code></td><td>Das Gerät verlangt einen Verschlüsselungsschlüssel, im Adapter fehlt er.</td></tr><tr><td><code>error</code></td><td>Anderer Fehler, die Meldung steht im Log.</td></tr></tbody></table><p>Bei <code>API password incorrect</code> und <code>Encryption Key Missing</code> hilft Warten nicht. Trag im Reiter „Geräte“ über „Verbindungseinstellungen ändern“ die richtigen Zugangsdaten ein.</p><h3 id="wenn-ein-gerat-offline-bleibt" tabindex="-1">Wenn ein Gerät offline bleibt <a class="header-anchor" href="#wenn-ein-gerat-offline-bleibt" aria-label="Permalink to &quot;Wenn ein Gerät offline bleibt&quot;">​</a></h3><ol><li>Lies im Log, was zu dem Gerät gemeldet wird. Die Bedeutung steht unter <a href="./log-meldungen#log-full-errors-connections-drop">Log-Meldungen</a>.</li><li>Prüfe, ob das Gerät im Netz erreichbar ist, z. B. über seine Webseite, falls es <code>web_server:</code> nutzt.</li><li>Starte das Gerät neu. Kommt es danach nicht von selbst zurück, starte die Instanz neu.</li></ol><p><strong>Siehe auch:</strong> <a href="./datenpunkte#online-status-wifi-signal-ip">Online-Status, WLAN-Signal und IP eines Geräts</a> · <a href="./../fehlerbehebung/verbindung#devices-offline-reporting-incorrect-password">Geräte sind nach Neustart offline oder melden &quot;incorrect password&quot;</a> · <a href="./../hintergrund/adapter-und-dashboard#adapter-dashboard-show-device-status">Warum Adapter und Dashboard den Status unterschiedlich zeigen</a></p><p><a id="show-configuration-states-info-config"></a></p><h2 id="was-bewirkt-die-option-konfigurationszustande-anzeigen-und-was-sind-die-ordner-info-und-config" tabindex="-1">Was bewirkt die Option &quot;Konfigurationszustände anzeigen&quot; und was sind die Ordner info und config? <a class="header-anchor" href="#was-bewirkt-die-option-konfigurationszustande-anzeigen-und-was-sind-die-ordner-info-und-config" aria-label="Permalink to &quot;Was bewirkt die Option &quot;Konfigurationszustände anzeigen&quot; und was sind die Ordner info und config?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',21)])])}const b=t(r,[["render",a]]);export{g as __pageData,b as default};
